// New dialogs use one selected UI language, with technical/provider names preserved.
static QString L(const char*en,const char*ar){return QString::fromUtf8(NasaqLanguage()=="ar"?ar:en);}
void Window::prayerSettings(){
 QDialog d(this);d.setObjectName("prayerSettings");d.setWindowTitle(NText("Prayer times"));d.resize(620,500);QVBoxLayout outer(&d);QScrollArea scroll;scroll.setWidgetResizable(true);scroll.setFrameShape(QFrame::NoFrame);auto content=new QWidget;QFormLayout form(content);scroll.setWidget(content);outer.addWidget(&scroll);
 QLabel note(L("Online source: AlAdhan. Choose a calculation authority and city. Calculated times may differ from your local mosque; verify before enabling adhan. Saved times remain available offline. Automatic refresh runs while NASAQ is open.","المصدر الإلكتروني: AlAdhan. اختر جهة الحساب والمدينة. قد تختلف المواقيت المحسوبة عن مسجدك؛ تحقق منها قبل تشغيل الأذان. تحفظ المواقيت محليًا وتحدّث تلقائيًا أثناء فتح نسق."));note.setWordWrap(true);form.addRow(&note);
 QComboBox country;country.setEditable(true);country.addItem(L("United Arab Emirates","الإمارات العربية المتحدة"),"AE");country.addItem(L("Saudi Arabia","السعودية"),"SA");country.addItem(L("Syria","سوريا"),"SY");country.addItem(L("Jordan","الأردن"),"JO");country.addItem(L("Egypt","مصر"),"EG");country.addItem(L("Qatar","قطر"),"QA");country.addItem(L("Kuwait","الكويت"),"KW");country.addItem(L("Bahrain","البحرين"),"BH");country.addItem(L("Oman","عُمان"),"OM");
 QComboBox city;city.setEditable(true);auto cities=[&]{city.clear();auto code=country.currentData().toString();if(code=="AE")city.addItems({"Dubai","Abu Dhabi","Sharjah","Ajman","Al Ain"});else if(code=="SA")city.addItems({"Riyadh","Makkah","Madinah","Jeddah","Dammam"});else if(code=="SY")city.addItems({"Damascus","Aleppo","Homs","Latakia"});else if(code=="JO")city.addItems({"Amman","Irbid"});else if(code=="EG")city.addItems({"Cairo","Alexandria"});else if(code=="QA")city.addItem("Doha");else if(code=="KW")city.addItem("Kuwait City");else if(code=="BH")city.addItem("Manama");else if(code=="OM")city.addItem("Muscat");};connect(&country,&QComboBox::currentIndexChanged,&d,cities);cities();
 if(!store.get("prayer_country").isEmpty()){int i=country.findData(store.get("prayer_country"));if(i>=0)country.setCurrentIndex(i);else country.setEditText(store.get("prayer_country"));}if(!store.get("prayer_city").isEmpty())city.setEditText(store.get("prayer_city"));
 form.addRow(L("Country (or enter a country name)","الدولة (أو أدخل اسم الدولة)"),&country);form.addRow(L("City (or enter another city)","المدينة (أو أدخل مدينة أخرى)"),&city);
 QComboBox method;method.addItem(L("Dubai","دبي"),16);method.addItem(L("Umm al-Qura, Makkah","أم القرى، مكة المكرمة"),4);method.addItem(L("Muslim World League","رابطة العالم الإسلامي"),3);method.addItem(L("Egyptian General Authority of Survey","الهيئة المصرية العامة للمساحة"),5);method.addItem(L("University of Islamic Sciences, Karachi","جامعة العلوم الإسلامية، كراتشي"),1);method.addItem(L("North America (ISNA)","أمريكا الشمالية"),2);method.addItem(L("Qatar","قطر"),10);method.addItem(L("Kuwait","الكويت"),9);method.setCurrentIndex(qMax(0,method.findData(store.get("prayer_method").toInt())));form.addRow(L("Calculation authority (via AlAdhan)","جهة الحساب (عبر AlAdhan)"),&method);
 QLabel automatic(L("Prayer times update automatically after you save your city. No monthly setup is needed.","تُحدّث المواقيت تلقائيًا بعد حفظ مدينتك، ولا تحتاج إلى إعداد الجدول كل شهر."));automatic.setObjectName("prayerAutomaticSchedule");automatic.setWordWrap(true);form.addRow(&automatic);
 QCheckBox pause(L("Automatically pause music at adhan","إيقاف الموسيقى تلقائيًا عند الأذان"));pause.setChecked(store.get("prayer_pause_enabled")!="0");form.addRow(&pause);
 QSpinBox pauseMinutes;pauseMinutes.setRange(1,60);pauseMinutes.setValue(store.get("prayer_pause_minutes").isEmpty()?10:store.get("prayer_pause_minutes").toInt());form.addRow(L("Pause duration (minutes)","مدة الإيقاف (دقائق)"),&pauseMinutes);

 QLineEdit adhan(store.get("prayer_audio"));adhan.setPlaceholderText(L("Leave empty for a silent prayer pause","اتركه فارغًا لإيقاف الموسيقى دون أذان"));QPushButton browse(NText("Choose audio"));form.addRow(L("Optional adhan file","ملف الأذان الاختياري"),&adhan);form.addRow(&browse);connect(&browse,&QPushButton::clicked,&d,[&]{auto f=QFileDialog::getOpenFileName(&d,NText("Choose audio"),{},"Audio (*.wav *.mp3 *.m4a *.aac);;All files (*)");if(!f.isEmpty())adhan.setText(f);});
 QTableWidget table;table.setColumnCount(2);table.setHorizontalHeaderLabels({L("Prayer","الصلاة"),L("Adhan time (city timezone)","موعد الأذان (بتوقيت المدينة)")});table.horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);table.setEditTriggers(QAbstractItemView::NoEditTriggers);table.setMinimumHeight(180);form.addRow(&table);
 auto preview=[&]{table.setRowCount(0);QTimeZone tz(store.get("prayer_timezone").toUtf8());auto q=store.query("SELECT id,due FROM events WHERE id LIKE 'prayer-api:%' AND status='pending' ORDER BY due LIMIT 15");while(q.next()){int row=table.rowCount();table.insertRow(row);auto name=q.value(0).toString().section(':',-1);if(NasaqLanguage()=="ar"){const QMap<QString,QString> names{{"Fajr",QStringLiteral("الفجر")},{"Dhuhr",QStringLiteral("الظهر")},{"Asr",QStringLiteral("العصر")},{"Maghrib",QStringLiteral("المغرب")},{"Isha",QStringLiteral("العشاء")}};name=names.value(name,name);}table.setItem(row,0,new QTableWidgetItem(name));auto time=QDateTime::fromMSecsSinceEpoch(q.value(1).toLongLong(),QTimeZone::UTC);table.setItem(row,1,new QTableWidgetItem(time.toTimeZone(tz.isValid()?tz:QTimeZone::UTC).toString("yyyy-MM-dd HH:mm t")));}};preview();
 QLabel result;result.setObjectName("prayerReadiness");result.setWordWrap(true);form.insertRow(1,&result);auto next=PrayerService::nextPause(store,QDateTime::currentDateTimeUtc());result.setText(store.get("prayer_pause_enabled")=="0"?L("Music pause is off. Enable automatic pause below and save to use this feature.","التوقف عند الأذان متوقف. فعّل إيقاف الموسيقى أدناه واحفظ لاستخدام الميزة."):next.isValid()?L("Next music pause: ","موعد إيقاف الموسيقى القادم: ")+next.toLocalTime().toString("yyyy-MM-dd HH:mm t"):L("First setup: choose your country, city and calculation authority, then press Save and update prayer times. You can also import a verified timetable.","للإعداد الأول: اختر الدولة والمدينة وجهة الحساب، ثم اضغط حفظ وتحديث المواقيت. يمكنك أيضًا استيراد جدول موثّق."));QPushButton save(L("Save and update prayer times","حفظ وتحديث المواقيت")),manual(L("Import a verified external timetable (JSON)","استيراد جدول خارجي موثّق (JSON)"));outer.addWidget(&save);form.addRow(&manual);connect(&manual,&QPushButton::clicked,&d,[this]{guarded([this]{importPrayers();});});
 connect(&save,&QPushButton::clicked,&d,[&]{save.setEnabled(false);result.setText(L("Fetching…","جارٍ الجلب…"));const auto code=country.currentIndex()>=0&&country.currentText()==country.itemText(country.currentIndex())?country.currentData().toString():country.currentText();try{audio.setPrayerPauseEnabled(pause.isChecked());store.set("prayer_pause_minutes",QString::number(pauseMinutes.value()));prayers.sync(city.currentText(),code,method.currentData().toInt(),adhan.text().trimmed());}catch(const std::exception&e){save.setEnabled(true);result.setText(QString::fromUtf8(e.what()));}});
 connect(&prayers,&PrayerService::completed,&d,[&](bool ok,const QString&m){save.setEnabled(true);preview();auto next=PrayerService::nextPause(store,QDateTime::currentDateTimeUtc());result.setText(ok?(store.get("prayer_pause_enabled")=="0"?L("Times saved. Automatic music pause is off.","حُفظت المواقيت. إيقاف الموسيقى تلقائيًا متوقف."):next.isValid()?L("Next music pause: ","موعد إيقاف الموسيقى القادم: ")+next.toLocalTime().toString("yyyy-MM-dd HH:mm t"):L("NOT READY: no upcoming music pause.","غير جاهز: لا يوجد موعد قادم لإيقاف الموسيقى.")):L("Could not update; the previous saved schedule is retained. ","تعذر التحديث؛ احتُفظ بالجدول السابق. ")+m);refresh();});
 QDialogButtonBox close(QDialogButtonBox::Close);form.addRow(&close);connect(&close,&QDialogButtonBox::rejected,&d,&QDialog::reject);ApplyNasaqFormDesign(&d);d.exec();
}
void Window::announcements(){StudioDialog dialog(studio,audio,this);dialog.exec();}
